import{_ as o,o as a,c as r,a5 as d}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"tc/latest/tutorial/core/logger.md","filePath":"tc/latest/tutorial/core/logger.md","lastUpdated":1788455378000}'),t={name:"tc/latest/tutorial/core/logger.md"};function c(l,e,n,i,g,s){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="日誌器-konadologger" tabindex="-1">日誌器 KonadoLogger <a class="header-anchor" href="#日誌器-konadologger" aria-label="Permalink to &quot;日誌器 KonadoLogger&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>KonadoLogger 是基於 Godot Logger 實作的日誌模組，支援日誌級別、日誌格式、日誌輸出、日誌檔案等功能，用於記錄 Konado 執行時的日誌資訊。</p><h2 id="日誌路徑" tabindex="-1">日誌路徑 <a class="header-anchor" href="#日誌路徑" aria-label="Permalink to &quot;日誌路徑&quot;">​</a></h2><p>日誌檔案的邏輯路徑為 <code>user://konado_log.log</code>，實際目錄由 Godot 依目前作業系統與專案名稱決定，可透過 <code>OS.get_user_data_dir()</code> 查看。<code>LOG_FILE_PATH</code> 是內建常數；如需改用其他路徑，應在維護自訂外掛版本時修改此常數。</p><h2 id="螢幕覆蓋日誌" tabindex="-1">螢幕覆蓋日誌 <a class="header-anchor" href="#螢幕覆蓋日誌" aria-label="Permalink to &quot;螢幕覆蓋日誌&quot;">​</a></h2><p>發生錯誤時，對話場景會在螢幕上覆蓋一個日誌視窗，用於顯示錯誤資訊並中斷遊戲執行。一般警告仍會寫入日誌檔案，但不會顯示為執行時錯誤或中斷遊戲。如果您希望關閉錯誤覆蓋視窗，可以將 <code>KonadoDialogueManager</code> 的 <code>enable_overlay_log</code> 屬性設定為 <code>false</code>。</p><h2 id="日誌回呼" tabindex="-1">日誌回呼 <a class="header-anchor" href="#日誌回呼" aria-label="Permalink to &quot;日誌回呼&quot;">​</a></h2><p><code>KonadoLogger</code> 實例會發出 <code>error_caught(msg)</code> 與 <code>message_caught(message, error)</code> 訊號。<code>KonadoDialogueManager</code> 進入場景樹時會建立內部日誌器並向 Godot 註冊，再以 <code>error_caught</code> 驅動畫面覆蓋日誌；它不是全域自動載入物件。自訂日誌整合若另行建立 <code>KonadoLogger</code>，必須使用 <code>OS.add_logger()</code> 註冊，並在釋放前使用 <code>OS.remove_logger()</code> 移除，避免重複記錄或殘留無效實例。</p><h2 id="執行時故障" tabindex="-1">執行時故障 <a class="header-anchor" href="#執行時故障" aria-label="Permalink to &quot;執行時故障&quot;">​</a></h2><p>原子指令執行失敗時，<code>KonadoDialogueManager</code> 只會寫入一筆最終錯誤，並發出 <code>runtime_failure_reported(failure)</code> 訊號。<code>failure</code> 包含穩定錯誤碼、具體操作、相關資源、底層原因、原始碼路徑與行號、指令 ID、操作碼及程式位置，可用於錯誤回報或自訂除錯介面。<code>runtime_failed(message, instruction_id, source_line)</code> 仍保留為精簡介面。</p>',11)])])}const u=o(t,[["render",c]]);export{h as __pageData,u as default};
